tool_input.command:
python - <<'E'
import uuid,re
g=str(uuid.uuid4())
s=open('Collection.cs').read()
s=s.replace("using Betta.Interfaces;","using Betta.Interfaces;\nusing Rhino.Geometry;",1)
s=s.rstrip()[:-1].rstrip()  # drop namespace close
s+=f'''

    public interface IGeometryPack : IBettaCollection
    {{
        [GrasshopperMethod("Divide Curve Stats", "Divide a curve into equal-length segments",
            Category = "Bench", SubCategory = "Geometry", Guid = "{g}")]
        (System.Collections.Generic.List<Point3d> Points, double Length) DivideCurveStats(
            [GrasshopperParameter("Curve")] Curve curve,
            [GrasshopperParameter("Count", DefaultValue = 10)] int count);
    }}

    public class GeometryPack : IGeometryPack
    {{
        public (System.Collections.Generic.List<Point3d> Points, double Length) DivideCurveStats(Curve curve, int count)
        {{
            if (curve == null) throw new System.ArgumentNullException(nameof(curve));
            if (count < 1) throw new System.ArgumentException("Count must be at least 1.", nameof(count));
            var parameters = curve.DivideByCount(count, true);
            var points = new System.Collections.Generic.List<Point3d>();
            if (parameters != null)
                foreach (var t in parameters) points.Add(curve.PointAt(t));
            return (points, curve.GetLength());
        }}
    }}
}}
'''
open('Collection.cs','w').write(s)
E
dotnet build 2>&1 | tail -8
